"""Run cache management tools for the AWS HealthOmics MCP server."""

import uuid
from awslabs.aws_healthomics_mcp_server.consts import (
    CACHE_BEHAVIORS,
    DEFAULT_MAX_RESULTS,
)
from awslabs.aws_healthomics_mcp_server.utils.aws_utils import (
    get_omics_client,
    get_s3_client,
)
from awslabs.aws_healthomics_mcp_server.utils.error_utils import (
    handle_tool_error,
)
from botocore.exceptions import ClientError
from datetime import datetime
from loguru import logger
from mcp.server.fastmcp import Context
from pydantic import Field
from typing import Any, Dict, Optional


async def create_run_cache(
    ctx: Context,
    cache_behavior: str = Field(
        ...,
        description="Cache behavior, one of 'CACHE_ALWAYS' or 'CACHE_ON_FAILURE'",
    ),
    cache_s3_location: str = Field(
        ...,
        description='S3 URI where the cache data will be stored (e.g. s3://my-bucket/prefix)',
    ),
    name: Optional[str] = Field(None, description='Name for the run cache'),
    description: Optional[str] = Field(None, description='Description for the run cache'),
    tags: Optional[Dict[str, str]] = Field(
        None, description='Tags to apply to the run cache'
    ),
    cache_bucket_owner_id: Optional[str] = Field(
        None, description='AWS account ID that owns the cache S3 bucket'
    ),
) -> Dict[str, Any]:
    """Create a new HealthOmics run cache.

    Args:
        ctx: MCP context for error reporting
        cache_behavior: Cache behavior, one of 'CACHE_ALWAYS' or 'CACHE_ON_FAILURE'
        cache_s3_location: S3 URI where the cache data will be stored
        name: Name for the run cache
        description: Description for the run cache
        tags: Tags to apply to the run cache
        cache_bucket_owner_id: AWS account ID that owns the cache S3 bucket

    Returns:
        Dictionary containing the created run cache (id, arn, status), or error dict
    """
    # Validate the cache behavior before doing anything else.
    if cache_behavior not in CACHE_BEHAVIORS:
        return await handle_tool_error(
            ctx,
            ValueError(
                f'Invalid cache behavior: {cache_behavior}. Must be one of {CACHE_BEHAVIORS}'
            ),
            'Error creating run cache',
        )

    # Validate the S3 URI format and extract the bucket name.
    if not cache_s3_location.startswith('s3://'):
        return await handle_tool_error(
            ctx,
            ValueError(
                f"Invalid S3 URI: {cache_s3_location}. Must start with 's3://'"
            ),
            'Error creating run cache',
        )

    bucket_name = cache_s3_location[len('s3://') :].split('/', 1)[0]
    if not bucket_name:
        return await handle_tool_error(
            ctx,
            ValueError(
                f'Invalid S3 URI: {cache_s3_location}. Missing bucket name'
            ),
            'Error creating run cache',
        )

    # Verify the bucket is accessible before creating the cache. Any S3 failure
    # here must prevent the HealthOmics create API from being called.
    try:
        s3_client = get_s3_client()
        s3_client.head_bucket(Bucket=bucket_name)
    except ClientError as e:
        error_code = e.response.get('Error', {}).get('Code', '')
        if error_code == '404':
            return await handle_tool_error(
                ctx,
                ValueError(f"S3 bucket '{bucket_name}' does not exist"),
                'Error creating run cache',
            )
        elif error_code == '403':
            return await handle_tool_error(
                ctx,
                ValueError(f"Access denied to S3 bucket '{bucket_name}'"),
                'Error creating run cache',
            )
        else:
            return await handle_tool_error(
                ctx, e, f'Error accessing S3 bucket {bucket_name}'
            )
    except Exception as e:
        return await handle_tool_error(
            ctx, e, f'Error accessing S3 bucket {bucket_name}'
        )

    try:
        client = get_omics_client()

        params: Dict[str, Any] = {
            'requestId': str(uuid.uuid4()),
            'cacheBehavior': cache_behavior,
            'cacheS3Location': cache_s3_location,
        }

        if name is not None:
            params['name'] = name

        if description is not None:
            params['description'] = description

        if tags is not None:
            params['tags'] = tags

        if cache_bucket_owner_id is not None:
            params['cacheBucketOwnerId'] = cache_bucket_owner_id

        logger.info(f'Creating run cache with params: {params}')
        response = client.create_run_cache(**params)

        return response
    except Exception as e:
        return await handle_tool_error(ctx, e, 'Error creating run cache')


async def get_run_cache(
    ctx: Context,
    cache_id: str = Field(..., description='ID of the run cache to retrieve'),
) -> Dict[str, Any]:
    """Get details of a specific HealthOmics run cache.

    Args:
        ctx: MCP context for error reporting
        cache_id: ID of the run cache to retrieve

    Returns:
        Dictionary containing the run cache details, or error dict
    """
    try:
        client = get_omics_client()

        logger.info(f'Getting run cache: {cache_id}')
        response = client.get_run_cache(id=cache_id)

        result: Dict[str, Any] = {}
        for key, value in response.items():
            if isinstance(value, datetime):
                result[key] = value.isoformat()
            else:
                result[key] = value

        return result
    except Exception as e:
        return await handle_tool_error(ctx, e, 'Error getting run cache')


